from typing import List

def checkMirrorTree(n: int, e: int, A: List[int], B: List[int]) -> int:
    def build_tree(edges):
        tree = {}
        for i in range(0, 2 * e, 2):
            u, v = edges[i], edges[i + 1]
            if u not in tree:
                tree[u] = []
            tree[u].append(v)
        return tree

    treeA = build_tree(A)
    treeB = build_tree(B)

    def is_mirror(root1, root2):
        if root1 not in treeA and root2 not in treeB:
            return True
        if root1 not in treeA or root2 not in treeB:
            return False
        childrenA = treeA[root1]
        childrenB = treeB[root2]
        if len(childrenA) != len(childrenB):
            return False
        return childrenA == childrenB[::-1] and all(is_mirror(a, b) for a, b in zip(childrenA, childrenB[::-1]))

    return 1 if is_mirror(1, 1) else 0
